mapper.select:
SELECT c.*, v.name as vaccine_name, v.image as vaccine_image, v.price as vaccine_price
FROM collection c
LEFT JOIN vaccine v ON c.vaccine_id = v.id

    AND c.user_id = #{userId}
    AND c.vaccine_id = #{vaccineId}

ORDER BY c.create_time DESC

SELECT COUNT(*) FROM collection c

    AND c.user_id = #{userId}
    AND c.vaccine_id = #{vaccineId}
